import{_ as e,o as t,c as o,a2 as n}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Armas y daño","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/combat/weapons-and-damage.md","filePath":"es/guide/combat/weapons-and-damage.md"}'),r={name:"es/guide/combat/weapons-and-damage.md"};function d(i,a,s,c,l,p){return t(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="weapons-and-damage" tabindex="-1">Armas y daño <a class="header-anchor" href="#weapons-and-damage" aria-label="Enlace permanente a &quot;Armas y daño&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto: identidades de armas · Aceptado: separación de salud y trauma · Experimental: equilibrio; comportamiento nuevo de armas no implementado.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Elige un arma por su distancia, ritmo y compromiso, no solo por su daño.</li><li>Corte, perforación e impacto contundente describen amenazas previstas distintas.</li><li>La calidad mejora un arma dentro de su función; no elimina sus contrapartidas.</li></ul><p><span id="weapons-and-damage-types"></span><span id="at-a-glance"></span><span id="trade-offs"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspecto</th><th>Significado</th></tr></thead><tbody><tr><td>Espada</td><td>Cortes y estocadas versátiles; control cercano fiable con alcance limitado.</td></tr><tr><td>Lanza</td><td>Distancia y presión perforante; más difícil de usar si el enemigo entra en su distancia preferida.</td></tr><tr><td>Martillo de guerra</td><td>Impacto contundente comprometido; fallar deja una recuperación costosa.</td></tr><tr><td>Daga / hacha</td><td>Oportunidades cortas y precisas / cortes e impacto estructural que exigen compromiso.</td></tr></tbody></table><p>Sangrado, fracturas y penetración de armadura son posibilidades futuras, no efectos automáticos de una familia de daño.</p><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Syrolands</th></tr></thead><tbody><tr><td>Las familias de armas ya tienen velocidades y ventajas distintas</td><td>Dar un papel central a la acción elegida, el alcance y el compromiso del que debes recuperarte.</td></tr><tr><td>Las mazas ya interactúan con armadura y resistencia en UOR</td><td>Ampliar las interacciones físicas sin convertir cada golpe contundente en una fractura garantizada.</td></tr></tbody></table><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un Heavy Blow fallado da tiempo al espadachín para responder. Un impacto mayor solo ayuda si puedes crear la oportunidad y asumir la recuperación.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/combat/reach-and-spacing.html">Alcance</a> · <a href="/Syrolands-Public/es/guide/combat/armor-and-protection.html">Armadura</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/weapons-and-damage.html">Leer la especificación de diseño completa</a></p><p><span id="choose-a-way-to-fight"></span><span id="read-the-encounter"></span></p>',17)])])}const h=e(r,[["render",d]]);export{u as __pageData,h as default};
